-- Bootstrap the first platform admin.
-- Run once against the production database after deploying the system-admin branch.
--
-- Creates the auth user, app_user, an organization, and platform_admin membership
-- all in one transaction. No sign-up page needed.
--
-- Usage:
--   psql "$DATABASE_URL" -f scripts/bootstrap-platform-admin.sql

BEGIN;

DO $$
DECLARE
  _uid  uuid;
  _oid  uuid;
  -- scrypt hash of 'barakaviv!8!2' generated by Better Auth's hashPassword()
  _hash text := 'be4884fabbef3812884361302e6f9f3e:7650e037ce5a1d13eed5b3615c44f8afe81b32e08b7fb255a233c9ddc760a8781bbad2e0debbf92a7ddada143b10ab4d9aed3d9a36385add9065c26b797f5653';
BEGIN

  -- 1. Create the auth user (or find existing)
  SELECT id INTO _uid
    FROM emb_auth."user"
   WHERE email = 'emazebrain@gmail.com';

  IF _uid IS NULL THEN
    _uid := gen_random_uuid();

    INSERT INTO emb_auth."user" (id, name, email, "emailVerified", "createdAt", "updatedAt")
    VALUES (_uid, 'eMazeBrain Admin', 'emazebrain@gmail.com', true, now(), now());

    RAISE NOTICE 'Created auth user: %', _uid;
  ELSE
    RAISE NOTICE 'Found existing auth user: %', _uid;
  END IF;

  -- 2. Link credential account (password)
  INSERT INTO emb_auth.account (id, "userId", "providerId", "accountId", password, "createdAt", "updatedAt")
  VALUES (gen_random_uuid(), _uid, 'credential', _uid, _hash, now(), now())
  ON CONFLICT DO NOTHING;

  RAISE NOTICE 'Credential account linked';

  -- 3. Create app_user row (active, not invited — this is the bootstrap admin)
  INSERT INTO app.app_user (id, email, full_name, kind, status)
  VALUES (_uid, 'emazebrain@gmail.com', 'eMazeBrain Admin', 'staff', 'active')
  ON CONFLICT (id) DO UPDATE SET status = 'active';

  RAISE NOTICE 'app_user active';

  -- 4. Ensure a default organization exists
  SELECT id INTO _oid FROM app.organization WHERE status = 'active' LIMIT 1;

  IF _oid IS NULL THEN
    INSERT INTO app.organization (name, region, default_locale, status)
    VALUES ('eMazeBrain', 'il', 'he', 'active')
    RETURNING id INTO _oid;
    RAISE NOTICE 'Created organization: %', _oid;
  ELSE
    RAISE NOTICE 'Using existing organization: %', _oid;
  END IF;

  -- 5. Create platform_admin membership (org-wide, no clinic)
  INSERT INTO app.membership (user_id, organization_id, clinic_id, role, status)
  VALUES (_uid, _oid, NULL, 'platform_admin', 'active')
  ON CONFLICT DO NOTHING;

  RAISE NOTICE 'Done — emazebrain@gmail.com is now platform_admin';
END $$;

COMMIT;
